class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF Core 9 uses "sync" semantics by default, but
        // SaveChanges on Cosmos now requires explicit patching or full replace.
        // No code change needed here, but raw SQL queries must be updated:
        //
        // OLD: SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // NEW (still works because we preserved "Discriminator" in OnModelCreating):
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        //
        // If you had NOT configured HasDiscriminator("Discriminator"), the new
        // default property name would be "$type" and queries would need:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

